import static org.junit.Assert.*;

public class Complex_divide_TriageGen2Test {

    private static final double EPSILON = 1e-10;

















    @Test
    public void testDivide_Branch_RealGreaterThanOrEqualImaginary() {
        // Logic: else { q = d / c; ... }
        // Let divisor = 2 + 1i -> c=2, d=1. |2| < |1| is false.
        Complex z = new Complex(4.0, 6.0);
        Complex divisor = new Complex(2.0, 1.0);
        // (4+6i)/(2+1i) = [(4+6i)(2-1i)] / [2^2 + 1^2] = [8 - 4i + 12i - 6i^2] / 5 = [14 + 8i] / 5 = 2.8 + 1.6i
        Complex result = z.divide(divisor);

        assertEquals(2.8, result.getReal(), EPSILON);
        assertEquals(1.6, result.getImaginary(), EPSILON);
    }


}

