public class Complex_divide_TriageGen2Test {

    private static final double EPSILON = 1e-10;



















    @Test
    public void testDivide_DivideByRealNumber() {
        Complex z = new Complex(10.0, 5.0);
        Complex divisor = new Complex(2.0, 0.0); // c=2, d=0. |2|<|0| is false.
        Complex result = z.divide(divisor);

        assertEquals(5.0, result.getReal(), EPSILON);
        assertEquals(2.5, result.getImaginary(), EPSILON);
    }
}
